func (o *AccessKey) LoadProject(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Project = nil
	o.R.Loaded.Project = false

	related, err := o.Project(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	o.R.Project = related
	o.R.Loaded.Project = true
	return nil
}

// LoadProject loads the accessKey's Project into the .R struct
func (os AccessKeySlice) LoadProject(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	projects, err := os.Project(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Project = nil
		o.R.Loaded.Project = true
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range projects {

			if !(o.ProjectID == rel.ID) {
				continue
			}

			o.R.Project = rel
			break
		}
	}

	return nil
}

type accessKeyJoins[Q dialect.Joinable] struct {
	typ     string
	Project modAs[Q, projectColumns]
}

func (j accessKeyJoins[Q]) aliasedAs(alias string) accessKeyJoins[Q] {
	return buildAccessKeyJoins[Q](buildAccessKeyColumns(alias), j.typ)
}

func buildAccessKeyJoins[Q dialect.Joinable](cols accessKeyColumns, typ string) accessKeyJoins[Q] {
	return accessKeyJoins[Q]{
		typ: typ,
		Project: modAs[Q, projectColumns]{
			c: Projects.Columns,
			f: func(to projectColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Projects.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.ProjectID),
					))
				}

				return mods
			},
		},
	}
}
